package com.hms.billing;
import com.hms.branches.*; import com.hms.doctors.*; import com.hms.staff.*; import java.util.*; import org.springframework.stereotype.Service;
@Service public class PlanLimitService {private final TenantSubscriptionRepository subscriptions;private final DoctorRepository doctors;private final HospitalStaffRepository staff;private final HospitalBranchRepository branches;public PlanLimitService(TenantSubscriptionRepository s,DoctorRepository d,HospitalStaffRepository st,HospitalBranchRepository b){subscriptions=s;doctors=d;staff=st;branches=b;} public void checkDoctor(UUID tenant){check(subscriptions.findById(tenant).map(TenantSubscription::getDoctorLimit).orElse(null),doctors.findAllByTenantIdOrderByDisplayName(tenant).size(),"doctor");} public void checkUser(UUID tenant){check(subscriptions.findById(tenant).map(TenantSubscription::getUserLimit).orElse(null),staff.findAllByTenantIdOrderByDisplayNameAsc(tenant).size(),"user");} public void checkBranch(UUID tenant){check(subscriptions.findById(tenant).map(TenantSubscription::getBranchLimit).orElse(null),branches.findAllByTenantIdOrderByNameAsc(tenant).size(),"branch");} private void check(Integer limit,int current,String type){if(limit!=null&&current>=limit)throw new IllegalArgumentException("Hospital plan "+type+" limit has been reached");}}
